# Obtén la tabla
table = self.getSibling("Table_0")  # Asegúrate de que el nombre del componente sea correcto

if table is not None:
    # Detección de cambios
    for row in range(len(table.props.data)):
        for col in range(len(table.props.columns)):
            tagPath = table.props.data[row]['tagPath']
            tagValue = system.tag.readBlocking([tagPath])[0].value

            if tagValue != table.props.data[row][table.props.columns[col].field]:
                # Realzar la celda cambiada (por ejemplo, cambiando el color de fondo)
                table.props.data[row][table.props.columns[col].field] = {
                    "value": tagValue,
                    "style": {"backgroundColor": "yellow"}
                }
else:
    print("El componente Table_0 no se encontró.")

transforms.code:
data = []
if not isinstance(value, list) or len(value) < 2:
    return value

# Recorremos las filas y detectamos cambios
for row_index, row in enumerate(value):
    formatted_row = {}  # Diccionario para la fila formateada

    for col, cell_value in row.items():
        # Inicializamos el objeto de la celda con su valor y estilo vacío
        cell_obj = {"value": cell_value, "style": {}}

        # Si no es la primera fila, comparamos con el valor anterior en la misma columna
        if row_index > 0:
            previous_value = value[row_index - 1].get(col)
            if cell_value != previous_value:
                # Si hay un cambio, se aplica el estilo para resaltar la celda
                cell_obj["style"] = {"backgroundColor": "yellow"}

        # Asignamos el objeto de la celda al diccionario de la fila
        formatted_row[col] = cell_obj

    # Añadimos la fila formateada al conjunto de datos
    data.append(formatted_row)

# Retornamos el nuevo conjunto de datos formateado
return data
